-- Access QueryDef: Справка_22-10_ОсвСтройки
-- Type: 0

SELECT ipgChRsltPlCstPercent.ogNm, ipgChRsltPlCstPercent.cstAgPnCode, ags_cstAgPn.cstapCstName, IIf(IsNull([ipgChRsltPlCstPercent]![ag_lim]),0,[ipgChRsltPlCstPercent]![ag_lim])+IIf(IsNull([ipgChRsltPlCstPercent]![iv_lim]),0,[ipgChRsltPlCstPercent]![iv_lim])+IIf(IsNull([ipgChRsltPlCstPercent]![uk_lim]),0,[ipgChRsltPlCstPercent]![uk_lim]) AS lim, ipgChRsltPlCstPercent.ag_lim, IIf([ipgChRsltPlCstPercent]![ag_PlFulfillment]+[ipgChRsltPlCstPercent]![ag_PlOverFulfillment]=0,Null,[ipgChRsltPlCstPercent]![ag_PlFulfillment]+[ipgChRsltPlCstPercent]![ag_PlOverFulfillment]) AS ag_Ful_OverFul, ([ipgChRsltPlCstPercent]![ag_PlFulfillment]+[ipgChRsltPlCstPercent]![ag_PlOverFulfillment])/[ipgChRsltPlCstPercent]![ag_lim] AS ag_LimPc, IIf([ag_PlOverLimit]=0,Null,[ag_PlOverLimit]) AS ag_PlOverLimit_, ipgChRsltPlCstPercent.iv_lim, ipgChRsltPlCstPercent.uk_lim
FROM ipgChRsltPlCstPercent LEFT JOIN ags_cstAgPn ON ipgChRsltPlCstPercent.cstAgPnCode = ags_cstAgPn.cstapIpgPnN
WHERE (((IIf(IsNull(ipgChRsltPlCstPercent!ag_lim),0,ipgChRsltPlCstPercent!ag_lim)+IIf(IsNull(ipgChRsltPlCstPercent!iv_lim),0,ipgChRsltPlCstPercent!iv_lim)+IIf(IsNull(ipgChRsltPlCstPercent!uk_lim),0,ipgChRsltPlCstPercent!uk_lim))>0) And ((ipgChRsltPlCstPercent.dateRslt)=#10/31/2022#))
ORDER BY ipgChRsltPlCstPercent.ogNm, ipgChRsltPlCstPercent.cstAgPnCode, IIf(IsNull([ipgChRsltPlCstPercent]![ag_lim]),0,[ipgChRsltPlCstPercent]![ag_lim])+IIf(IsNull([ipgChRsltPlCstPercent]![iv_lim]),0,[ipgChRsltPlCstPercent]![iv_lim])+IIf(IsNull([ipgChRsltPlCstPercent]![uk_lim]),0,[ipgChRsltPlCstPercent]![uk_lim]) DESC , ipgChRsltPlCstPercent.dateRslt;
